
import { fileURLToPath } from 'url';
import { logError } from "./logError.mjs";
const msInYear = 1000 * 60 * 60 * 24 * 365.25;

export const calcAge = dateBirth => {
  try {
    let date = new Date(dateBirth);
    let msAge = Date.now() - date;
    return ((msAge / msInYear)|| 0).toFixed(0) ;
  } catch (error) {
    const __filename = fileURLToPath(import.meta.url);
    logError(error, path.parse(__filename).name);
    return 0;
  }
};
